#!/usr/bin/env bash
# ballot-parse.sh — Parse review ballot finding blocks.

set -euo pipefail

usage() { echo "Usage: ballot-parse.sh --ballot-file FILE" >&2; }

BALLOT_FILE=""
while [[ $# -gt 0 ]]; do
    case "$1" in
        --ballot-file) BALLOT_FILE="${2:?--ballot-file requires a value}"; shift 2 ;;
        --help) usage; exit 0 ;;
        *) echo "ballot-parse.sh: unknown option: $1" >&2; usage; exit 2 ;;
    esac
done

[[ -n "$BALLOT_FILE" && -f "$BALLOT_FILE" ]] || { echo "ballot-parse.sh: --ballot-file must name a file" >&2; exit 2; }

awk '
function emit() {
    if (idx > 0) {
        gsub(/^[[:space:]]+|[[:space:]]+$/, "", concern)
        printf("FINDING_%d_TITLE=%s\n", idx, title)
        printf("FINDING_%d_CONCERN=%s\n", idx, concern)
        printf("FINDING_%d_OOS=%s\n", idx, oos)
    }
}
/^### FINDING_[0-9]+:/ {
    emit()
    idx++
    title=$0
    sub(/^### FINDING_[0-9]+:[[:space:]]*/, "", title)
    concern=""
    oos="false"
    if (title ~ /^\[OUT_OF_SCOPE\]/ || title ~ /^\[OOS\]/) oos="true"
    next
}
idx > 0 {
    if ($0 ~ /^- \*\*Concern\*\*:/) {
        line=$0
        sub(/^- \*\*Concern\*\*:[[:space:]]*/, "", line)
        concern=line
    } else if (concern != "" && $0 !~ /^- \*\*/) {
        concern=concern " " $0
    }
    if ($0 ~ /\[OUT_OF_SCOPE\]/ || $0 ~ /\[OOS\]/) oos="true"
}
END {
    emit()
    printf("FINDING_COUNT=%d\n", idx + 0)
}
' "$BALLOT_FILE"

#!/usr/bin/env bash
# tally-vote.sh — Apply review vote thresholds to ballot findings.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)"

usage() { echo "Usage: tally-vote.sh --ballot-file FILE --voter-files FILE..." >&2; }

BALLOT_FILE=""
VOTER_FILES=()
while [[ $# -gt 0 ]]; do
    case "$1" in
        --ballot-file) BALLOT_FILE="${2:?--ballot-file requires a value}"; shift 2 ;;
        --voter-files)
            shift
            while [[ $# -gt 0 && "$1" != --* ]]; do VOTER_FILES+=("$1"); shift; done
            ;;
        --help) usage; exit 0 ;;
        *) echo "tally-vote.sh: unknown option: $1" >&2; usage; exit 2 ;;
    esac
done

[[ -n "$BALLOT_FILE" && -f "$BALLOT_FILE" ]] || { echo "tally-vote.sh: --ballot-file must name a file" >&2; exit 2; }

parse_out=$("$SCRIPT_DIR/ballot-parse.sh" --ballot-file "$BALLOT_FILE")
count=$(printf '%s\n' "$parse_out" | awk -F= '$1=="FINDING_COUNT"{print $2}')
count=${count:-0}

idx=1
while [[ "$idx" -le "$count" ]]; do
    yes=0
    no=0
    exon=0
    for vf in "${VOTER_FILES[@]}"; do
        [[ -f "$vf" ]] || continue
        vote=$(awk -v n="$idx" '
            BEGIN { vote="" }
            $0 ~ ("^FINDING_" n "([^0-9]|$)") {
                if ($0 ~ /EXONERATE/) vote="EXONERATE";
                else if ($0 ~ /YES/) vote="YES";
                else if ($0 ~ /NO/) vote="NO";
            }
            END { print vote }
        ' "$vf")
        case "$vote" in
            YES) yes=$((yes + 1)) ;;
            NO) no=$((no + 1)) ;;
            EXONERATE) exon=$((exon + 1)) ;;
        esac
    done
    accepted=false
    voter_count="${#VOTER_FILES[@]}"
    if [[ "$voter_count" -lt 2 ]]; then
        # Fewer than 2 eligible voters: voting protocol requires accept-all (rows 15-16).
        accepted=true
    elif [[ "$yes" -ge 2 ]]; then
        accepted=true
    fi
    # 1Y/1N split (tie-breaker) is handled by the caller (tally-votes.sh);
    # tally-vote.sh only reports raw YES/NO/EXONERATE counts.
    printf 'FINDING_%s_ACCEPTED=%s\n' "$idx" "$accepted"
    printf 'FINDING_%s_VOTES_YES=%s\n' "$idx" "$yes"
    printf 'FINDING_%s_VOTES_NO=%s\n' "$idx" "$no"
    printf 'FINDING_%s_VOTES_EXONERATE=%s\n' "$idx" "$exon"
    idx=$((idx + 1))
done
printf 'FINDING_COUNT=%s\n' "$count"
